pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(uint256 proposalID) internal {
        try c.init(address(0x1), address(0x2), address(0x3)) {} catch { return; }
        bool reverted;
        try c.finaliseProposal(proposalID) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 proposalID) public {
        _run(proposalID);
    }

    receive() external payable {}
}
